:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-linen-surface: #fcfbf9;
  --color-parchment-wash: #f8f6f3;
  --color-frosted-glass: #ffffffb3;
  --color-jet-panel: #000000;
  --color-carbon-fill: #2b2926;
  --color-ink: #1a1916;
  --color-pebble-caption: #7b736c;
  --color-stone-hairline: #eeece6;
  --color-mint-signal: #a7f3d0;
  --color-mint-wash: #d1fae5;
  --color-forest-ink: #064e3b;
  --color-sunbeam-highlight: #fdffa2;

  /* Typography — Font Families */
  --font-rhymes-display: "Rhymes Display", "Newsreader", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-roboto-mono: "Roboto Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.67;
  --tracking-small: 0px;
  --text-caption: 12px;
  --leading-caption: 1.33;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.43;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-subheading: 20px;
  --leading-subheading: 1.4;
  --tracking-subheading: 0px;
  --text-heading-sm: 24px;
  --leading-heading-sm: 1.25;
  --tracking-heading-sm: 0px;
  --text-heading: 36px;
  --leading-heading: 0.94;
  --tracking-heading: -0.2px;
  --text-heading-lg: 44px;
  --leading-heading-lg: 1.14;
  --tracking-heading-lg: -0.2px;
  --text-display: 80px;
  --leading-display: 0.8;
  --tracking-display: -1.5px;

  /* Typography — Weights */
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-60: 60px;
  --spacing-80: 80px;
  --spacing-140: 140px;
  --spacing-160: 160px;

  /* Layout */
  --layout-max-width: 1200px;
  --layout-section-gap: 80px;
  --layout-card-padding: 20px;
  --layout-element-gap: 12px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 10px;
  --radius-2xl: 12px;
  --radius-full: 999px;

  /* Named Radii */
  --radius-smallElements: 4px;
  --radius-buttons: 6px;
  --radius-images: 6px;
  --radius-cards: 8px;
  --radius-nav: 10px;
  --radius-tags: 10px;
  --radius-badges: 10px;
  --radius-sections: 12px;
  --radius-avatars: 999px;

  /* Shadows */
  --shadow-subtle: rgba(0, 0, 0, 0.08) 0px 0px 0px 1px, rgba(0, 0, 0, 0.12) 0px 1px 2px 0px;
  --shadow-sm: rgba(255, 255, 255, 0.2) 0px 0.75px 0px 0px inset, rgba(0, 0, 0, 0.4) 0px 1px 2px 0px, rgb(24, 24, 27) 0px 0px 0px 1px;
  --shadow-sm-2: rgba(0, 0, 0, 0.2) 0px 1px 2px 0px, rgb(167, 243, 208) 0px 0px 0px 1px, rgba(255, 255, 255, 0.2) 0px 0.75px 0px 0px inset;
  --shadow-md: rgba(0, 0, 0, 0.1) 0px 2px 8px 0px, rgba(0, 0, 0, 0.08) 0px 1px 2px -1px, rgba(0, 0, 0, 0.08) 0px 0px 0px 1px;
  --shadow-md-2: rgba(43, 41, 38, 0.08) 0px 0px 0px 1px, rgba(0, 0, 0, 0.08) 0px 1px 2px -1px, rgba(0, 0, 0, 0.1) 0px 2px 8px 0px;

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-parchment-wash: #f8f6f3;
  --surface-linen-surface: #fcfbf9;
  --surface-frosted-glass: #ffffffb3;
  --surface-jet-panel: #000000;
}

